package ru.kupiora.radar;
import android.location.*;import android.os.*;import android.widget.Toast;import java.util.*;
final class RegionLocator implements LocationListener {
 final MainActivity activity;final LocationManager manager;final Handler handler=new Handler(Looper.getMainLooper());boolean finished=false;final Runnable timeout=()->fail("Не удалось определить регион. Выберите его вручную.");
 RegionLocator(MainActivity a){activity=a;manager=(LocationManager)a.getSystemService(android.content.Context.LOCATION_SERVICE);}
 void start(){try{if(activity.checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){fail("Разрешение на геолокацию не предоставлено.");return;}if(!Geocoder.isPresent()){fail("Определение названия региона недоступно. Выберите регион вручную.");return;}String provider=manager.isProviderEnabled(LocationManager.NETWORK_PROVIDER)?LocationManager.NETWORK_PROVIDER:null;if(provider==null){fail("Геолокация выключена. Выберите регион вручную или включите её в настройках телефона.");return;}Toast.makeText(activity,"Определяем регион…",Toast.LENGTH_SHORT).show();manager.requestSingleUpdate(provider,this,Looper.getMainLooper());handler.postDelayed(timeout,30000);}catch(Exception e){fail("Нет доступа к местоположению. Можно выбрать регион вручную.");}}
 public void onLocationChanged(Location location){if(finished)return;manager.removeUpdates(this);handler.removeCallbacks(timeout);handler.postDelayed(timeout,15000);new Thread(()->{try{List<Address> found=new Geocoder(activity,new Locale("ru","RU")).getFromLocation(location.getLatitude(),location.getLongitude(),1);String region=null;if(found!=null&&!found.isEmpty()&&"RU".equalsIgnoreCase(found.get(0).getCountryCode()))region=found.get(0).getAdminArea();final String result=region;handler.post(()->{if(finished||activity.isFinishing()||activity.isDestroyed())return;if(result==null||result.isEmpty()){fail("Регион России не определён. Выберите его вручную.");return;}close();new android.app.AlertDialog.Builder(activity).setTitle("Ваш регион — "+result+"?").setMessage("Использовать его для стоимости корзины?").setNegativeButton("Нет",(d,w)->BasketScreen.choose(activity)).setPositiveButton("Да",(d,w)->{Store.prefs(activity).edit().putString("basket_region",result).apply();activity.show("basket");}).show();});}catch(Exception e){handler.post(()->fail("Не удалось получить название региона. Выберите его вручную."));}},"basket-region").start();}
 public void onProviderDisabled(String provider){fail("Геолокация выключена. Выберите регион вручную.");}public void onProviderEnabled(String p){}public void onStatusChanged(String p,int status,Bundle extras){}
 void fail(String message){if(finished)return;close();if(!activity.isFinishing()&&!activity.isDestroyed())Toast.makeText(activity,message,Toast.LENGTH_LONG).show();}
 void close(){finished=true;handler.removeCallbacksAndMessages(null);try{manager.removeUpdates(this);}catch(Exception ignored){}}
}
